     7	export function useRegisterFieldControl(
     8	  controlRef: FieldControlRegistration['controlRef'],
     9	  id: FieldControlRegistration['id'],
    10	  value: FieldControlRegistration['value'],
    11	  getFormValueOverride?: FieldControlRegistration['getValue'],
    12	  enabled = true,
    13	  name?: FieldControlRegistration['name'],
    14	) {
    15	  const { registerFieldControl } = useFieldRootContext();
    16	  const sourceRef = useRefWithInit(() => Symbol());
    17	
    18	  // Re-register without unregistering first: re-registration with the same id updates the
    19	  // form's fields Map entry in place, while a delete + re-add would move the field to the
    20	  // end of the Map every time its value changes.
    21	  useIsoLayoutEffect(() => {
    22	    const source = sourceRef.current;
    23	
    24	    if (!enabled) {
    25	      registerFieldControl(source, undefined);
    26	      return;
    27	    }
    28	
    29	    const registration: FieldControlRegistration = {
    30	      controlRef,
    31	      getValue: getFormValueOverride,
    32	      id,
    33	      name,
    34	      value,
    35	    };
    36	
    37	    registerFieldControl(source, registration);
    38	  }, [controlRef, enabled, getFormValueOverride, id, name, registerFieldControl, sourceRef, value]);
    39	
    40	  useIsoLayoutEffect(() => {
    41	    const source = sourceRef.current;
    42	    return () => {
    43	      registerFieldControl(source, undefined);
    44	    };
    45	  }, [registerFieldControl, sourceRef]);
