106	    if (!registration || !registration.id) {
107	      return;
108	    }
109	
110	    setRegisteredFieldName(name ? undefined : registration.name);
111	
112	    formRef.current.fields.set(registration.id, {
113	      getValue: getValueForForm,
114	      name: name ?? registration.name,
115	      controlRef: registration.controlRef,
116	      validityData: getCombinedFieldValidityData(validityData, invalid),
