121	  useIsoLayoutEffect(() => {
122	    const fields = formRef.current.fields;
123	
124	    return () => {
125	      const id = registrationRef.current?.id;
126	      if (id) {
127	        fields.delete(id);
128	      }
129	    };
130	  }, [formRef]);
