137	          deleteRegistration();
138	          registrationRef.current = null;
139	          setRegisteredFieldName(undefined);
140	          registeredFieldIdRef.current = undefined;
141	        }
142	        return;
143	      }
144	
145	      const previousId = registrationRef.current?.id;
146	
147	      activeFieldControlSourceRef.current = source;
148	      registrationRef.current = registration;
149	      if (!name) {
150	        setRegisteredFieldName(registration.name);
151	      }
152	      registeredFieldIdRef.current = registration.id;
153	
154	      if (previousId && previousId !== registration.id) {
155	        deleteRegistration(previousId);
156	      }
157	
158	      captureInitialValue(registration);
159	      refreshRegistration();
160	    },
161	  );
162	
163	  return [validate, register] as const;
164	}
165	
166	export interface UseFieldControlRegistrationParameters {
167	  commit: (value: unknown) => void;
168	  invalid: boolean;
169	  markedDirtyRef: React.RefObject<boolean>;
170	  name: string | undefined;
171	  setRegisteredFieldName: (name: string | undefined) => void;
172	  registeredFieldIdRef: React.RefObject<string | undefined>;
173	  setValidityData: React.Dispatch<React.SetStateAction<FieldValidityData>>;
174	  validityData: FieldValidityData;
175	}

