import * as React from 'react';
import { expect, it, describe, vi, afterEach } from 'vitest';
import { render, fireEvent, screen, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControl as OldControl } from './OldFieldControl';

afterEach(cleanup);

const variants = [
  ['new', Field.Control],
  ['old', OldControl],
] as const;

describe.each(variants)('%s', (label, Control: any) => {
  it('render count per keystroke, onChange mode controlled', () => {
    const counts = { control: 0 };
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={() => null}>
          <Control
            data-testid="c"
            value={value}
            onValueChange={setValue}
            render={(props: any) => {
              counts.control += 1;
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    const c = screen.getByTestId('c');
    fireEvent.change(c, { target: { value: 'a' } });
    const settled = counts.control;
    fireEvent.change(c, { target: { value: 'ab' } });
    fireEvent.change(c, { target: { value: 'abc' } });
    console.log(label, 'onChange-mode renders for 2 keystrokes:', counts.control - settled);
  });

  it('reset to empty after typing, required, onChange mode', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange">
          <Control data-testid="c" required value={value} onValueChange={setValue} />
          <Field.Error match="valueMissing">Required</Field.Error>
          <button type="button" onClick={() => setValue('')}>reset</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByTestId('c'), { target: { value: 'abc' } });
    fireEvent.click(screen.getByText('reset'));
    const root = screen.getByTestId('root');
    console.log(
      label,
      'after reset: dirty=',
      root.hasAttribute('data-dirty'),
      'invalid=',
      root.hasAttribute('data-invalid'),
      'requiredShown=',
      !!screen.queryByText('Required'),
    );
  });

  it('async loaded value', async () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      React.useEffect(() => {
        setTimeout(() => setValue('Loaded'), 0);
      }, []);
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control data-testid="c" value={value} onValueChange={setValue} />
        </Field.Root>
      );
    }
    render(<App />);
    await act(async () => {
      await new Promise((r) => setTimeout(r, 10));
    });
    const root = screen.getByTestId('root');
    console.log(label, 'after async load: dirty=', root.hasAttribute('data-dirty'), 'filled=', root.hasAttribute('data-filled'), 'validateCalls=', validate.mock.calls.length);
  });

  it('submit validator value type for numeric controlled', () => {
    const validate = vi.fn((_v: unknown) => null);
    render(
      <Form>
        <Field.Root name="n" validate={validate}>
          <Control value={5} onValueChange={() => {}} />
        </Field.Root>
        <button type="submit">submit</button>
      </Form>,
    );
    fireEvent.click(screen.getByText('submit'));
    console.log(label, 'submit validate arg:', JSON.stringify(validate.mock.calls.map((c) => c[0])));
  });

  it('server error cleared when user retypes identical value (controlled)', () => {
    function App() {
      const [value, setValue] = React.useState('a');
      return (
        <Form errors={{ m: 'Server error' }}>
          <Field.Root name="m">
            <Control data-testid="c" value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByTestId('c'), { target: { value: 'ab' } });
    console.log(label, 'server error after typing:', !!screen.queryByText('Server error'));
  });

  it('controlled + preventDefault on input', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ m: 'Server error' }}>
          <Field.Root name="m" validationMode="onChange">
            <Control data-testid="c" value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const c = screen.getByTestId('c');
    c.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
    fireEvent.input(c, { cancelable: true, target: { value: 'a' } });
    console.log(label, 'prevented controlled: server error kept=', !!screen.queryByText('Server error'));
  });
});

